#!/usr/bin/env python3
"""Serve generated bytes and controlled disconnections for native download tests."""
import argparse
import json
import socket
import time
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, urlparse


class FixtureHandler(BaseHTTPRequestHandler):
    recovered = set()
    interrupted = set()

    def log_message(self, *_args):
        pass

    def do_GET(self):
        url = urlparse(self.path)
        case = parse_qs(url.query).get('case', ['default'])[0]
        if url.path == '/recover':
            self.recovered.add(case)
            self.send_response(200)
            self.end_headers()
            return
        slow = url.path == '/slow.wav'
        if not slow and case in self.interrupted and case not in self.recovered:
            self.send_response(503)
            self.end_headers()
            return
        length = 8 * 1024 * 1024 if slow else 512 * 1024
        self.send_response(200)
        self.send_header('Content-Type', 'audio/wav')
        self.send_header('Content-Length', str(length))
        self.end_headers()
        try:
            chunk = bytes(64 * 1024)
            if not slow and case not in self.recovered:
                self.interrupted.add(case)
                self.wfile.write(chunk)
                self.wfile.flush()
                self.connection.shutdown(socket.SHUT_RDWR)
                self.connection.close()
                return
            for _ in range(length // len(chunk)):
                self.wfile.write(chunk)
                self.wfile.flush()
                time.sleep(.15 if slow else .02)
        except (BrokenPipeError, ConnectionResetError, OSError):
            pass


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--bind', default='127.0.0.1')
    parser.add_argument('--port', type=int, default=0)
    args = parser.parse_args()
    server = ThreadingHTTPServer((args.bind, args.port), FixtureHandler)
    print(json.dumps({'port': server.server_port}), flush=True)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()


if __name__ == '__main__':
    main()
